def icon(glyph, rp, acc):
    im = Image.new('RGBA', (16, 16), (0, 0, 0, 0)); a2 = tuple(min(255, int(v * 1.2) + 20) for v in acc)
    col = {'#': rp[3], '+': rp[5], '-': rp[1], 'a': acc, 'A': a2}
    for y, row in enumerate(G[glyph]):
        for x, ch in enumerate(row):
            if ch in col: im.putpixel((x + 2, y + 2), col[ch] + (255,))
    src = im.copy()
    for y in range(16):
        for x in range(16):
            if src.getpixel((x, y))[3]: continue
            if any(0 <= x + dx < 16 and 0 <= y + dy < 16 and src.getpixel((x + dx, y + dy))[3] for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                im.putpixel((x, y), rp[0] + (255,))
    return im
src = open(ROOT + 'Siege_Nights_BP/scripts/townhall/skills.js').read()
skills = re.findall(r'^\s*S\("([^"]+)",\s*"([^"]+)"', src, re.M)
os.makedirs(OUT, exist_ok=True); done = []; miss = []
for sid, br in skills:
    g = PICK.get(sid)
    if not g: miss.append(sid); g = 'star'
    im = icon(g, BR[br], ACC[br]); im.save(OUT + sid + '.png'); done.append((br, sid, im))
done.sort(key=lambda t: (list(BR).index(t[0]), t[1]))
sh = Image.new('RGBA', (15 * 56 + 8, 8 * 56 + 8), (38, 34, 46, 255)); row = {b: 0 for b in BR}
for br, sid, im in done:
    sh.alpha_composite(im.resize((48, 48), Image.NEAREST), (8 + row[br] * 56, 8 + list(BR).index(br) * 56)); row[br] += 1
sh.save(ROOT + 'art/skill-icons.png'); print('ok', len(done), 'no glyph:', miss)
for b in BR:
    used = [PICK.get(s) for s, x in skills if x == b]; assert len(used) == len(set(used)), (b, used)
